  "tests": null,
  "hypothesis_updates": null,
  "carryover": {
    "COMPLETED": "All hypotheses evaluated; determined reason for dual concept usage and appropriate concept per year.",
    "REMAINING": "None",
    "DECISIONS": "Use legacy 'Revenues' for 2011‑2017; from 2018 onward either concept works, prefer ASC 606 for new analysis.",
    "CONTEXT": "Evidence shows ASC 606 adoption in 2018 with parallel tagging; values generally match, indicating same revenue figure."
  },
  "answer": {
    "summary": "Tesla originally tagged its revenue with the legacy US‑GAAP concept 'Revenues'. After adopting ASC 606 in 2018, it began tagging the same revenue amount with the newer concept 'RevenueFromContractWithCustomerExcludingAssessedTax', resulting in parallel tagging from 2018 onward. For 2011‑2017 only the legacy concept appears; from 2018 onward both concepts are present and contain identical values, so either can be used.",
    "claims": [
      {
        "text": "Tesla reported only the 'Revenues' concept for fiscal years 2011‑2017, with fact counts of 21‑22 per year and no ASC 606 concept in those years.",
        "evidence": ["E-763045", "E-a15cd5", "E-8291d0", "E-e904c5", "E-59c5aa", "E-a6bd98"]
      },
      {
        "text": "Starting in fiscal year 2018, Tesla reported revenue under both 'Revenues' and 'RevenueFromContractWithCustomerExcludingAssessedTax' concepts.",
        "evidence": ["E-a6bd98", "E-763045", "E-a15cd5", "E-8291d0", "E-e904c5", "E-59c5aa"]
      },
      {
        "text": "For accession numbers that contain both concepts, the reported USD values are identical (e.g., 3408751000, 7410982000), indicating the tags represent the same revenue figure.",
        "evidence": ["E-844982"]
      }
    ],
    "inferences": [
      {
        "text": "The dual concept usage reflects Tesla's adoption of the ASC 606 revenue recognition standard effective 2018, leading to parallel XBRL tagging during and after the transition.",
        "basis": ["Claims 1 and 2"]
      },
      {
        "text": "Because the values are identical, either concept can be used for financial analysis from 2018 onward; the ASC 606 concept aligns with current GAAP but the legacy concept remains valid for continuity.",
        "basis": ["Claim 3"]
      }
    ],
    "hypothesis_verdicts": [
      {
        "id": "H-3b9440",
        "status": "supported",
        "evidence": ["E-0e3ef9", "E-763045", "E-a6bd98"],
        "why": "Shows initial use of Revenues and later appearance of ASC 606 concept, consistent with a standard-driven shift."
      },
      {
        "id": "H-d0b0d7",
        "status": "refuted",
        "evidence": ["E-d1d862"],
        "why": "Amended filings do not explain duplicate tagging; both concepts appear in original filings as well."
      },
      {
        "id": "H-e2ec90",
        "status": "refuted",
        "evidence": ["E-844982"],
        "why": "Values of the two concepts are identical, showing no difference in scope."
      },
      {
        "id": "H-5e94de",
        "status": "refuted",
        "evidence": ["E-0e3ef9", "E-d1d862"],
        "why": "Evidence does not support tagging errors; duplicate concepts appear consistently after 2018, not as sporadic mistakes."
      }
    ]
  }
}
